}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb .separator {
  color: var(--text-muted);
}

/* --- Tabs --- */
.tab-list {
  display: flex;
  gap: var(--space-xs);
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: var(--space-xs);
}

.tab-list::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  white-space: nowrap;
  color: var(--text-secondary);
  background-color: var(--warm-gray);
  transition: all var(--transition-fast);
  border: 1.5px solid transparent;
}

.tab-btn:hover {
  color: var(--green-primary);
  background-color: var(--green-light);
}

.tab-btn.is-active {
  color: white;
  background-color: var(--green-primary);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease-out;
}

.tab-panel.is-active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform 0.4s ease-out;
}

.carousel-slide {
  flex: 0 0 calc(33.333% - var(--space-lg) * 2 / 3);
  min-width: 0;
}

@media (max-width: 767px) {
  .carousel-slide {
    flex: 0 0 calc(80%);
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .carousel-slide {
    flex: 0 0 calc(50% - var(--space-lg) / 2);
  }
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background-color: white;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-50%) scale(1.05);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-btn:disabled:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-50%);
}

.carousel-btn-prev {
  left: var(--space-md);
}

.carousel-btn-next {
  right: var(--space-md);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
  stroke: var(--text-primary);
}

/* --- Gift Card Styles --- */
.gift-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
  aspect-ratio: 3/2;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: var(--space-lg);
  position: relative;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.gift-card-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.1;
}

.gift-card-content {
  position: relative;
  z-index: 1;
}

.gift-card-content h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.gift-card-content p {
  font-size: 0.75rem;
  opacity: 0.8;
}

/* --- Form Controls --- */
.input-group {
  position: relative;
}

.input-field {
  width: 100%;
  padding: 0.875rem 1rem;
  font-family: var(--font-body);
  font-size: 1rem;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: white;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.input-field:focus {
  outline: none;
  border-color: var(--green-primary);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.15);
}

.input-field::placeholder {
  color: var(--text-muted);
}

/* --- Toggle Switch --- */
.toggle-group {
  display: inline-flex;
  background-color: var(--warm-gray);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-btn {
  padding: 0.5rem 1.25rem;
  font-weight: 600;
  font-size: 0.875rem;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}

.toggle-btn.is-active {
  background-color: white;
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

/* --- Filter Panel --- */
.filter-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.filter-panel.is-open {
  max-height: 500px;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--green-primary);
}

/* --- Store Card --- */
.store-card {
  background-color: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 1px solid var(--border-color);
  transition: all var(--transition-base);
}

.store-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.store-card h3 {
  font-family: var(--font-body);
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.store-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.store-features {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin-top: var(--space-md);
}

.store-feature-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  background-color: var(--green-light);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
}

/* --- Sidebar --- */
.sidebar {
  width: 100%;
  border-right: 1px solid var(--border-color);
  padding: var(--space-xl);
}

@media (min-width: 1024px) {
  .sidebar {
    width: 280px;
    flex-shrink: 0;
    position: sticky;
    top: var(--header-height);
    height: calc(100vh - var(--header-height));
    overflow-y: auto;
  }
}

.sidebar-group {
  margin-bottom: var(--space-xl);
}

.sidebar-group h3 {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--green-primary);
  margin-bottom: var(--space-sm);
}

.sidebar-group ul li a {
  display: block;
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.sidebar-group ul li a:hover,
.sidebar-group ul li a.is-active {
  color: var(--green-primary);
  font-weight: 600;
}

/* --- Redemption Levels --- */
.redemption-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

@media (min-width: 768px) {
  .redemption-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .redemption-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.redemption-card {
  background-color: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 2px solid var(--border-color);
  text-align: center;
  transition: all var(--transition-base);
}

.redemption-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-md);
}

.redemption-card .stars {
  font-size: 2rem;
  color: var(--cream-dark);
  font-weight: 700;
  font-family: var(--font-heading);
  margin-bottom: var(--space-sm);
}

.redemption-card h4 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.redemption-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* --- Tier Cards --- */
.tier-card {
  background-color: white;
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  border: 2px solid var(--border-color);
  transition: all var(--transition-base);
}

.tier-card:hover {
  border-color: var(--green-primary);
}

.tier-card.gold {
  border-color: var(--cream);
  background: linear-gradient(135deg, #FFFDF7 0%, #FDF6E3 100%);
}

.tier-card.reserve {
  border-color: var(--forest);
  background: linear-gradient(135deg, var(--forest) 0%, #3E4A3C 100%);
  color: white;
}

.tier-card.reserve p,
.tier-card.reserve li {
  color: rgba(255, 255, 255, 0.8);
}

.tier-card h3 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xs);
}

.tier-card .tier-threshold {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}

.tier-card.reserve .tier-threshold {
  color: rgba(255, 255, 255, 0.5);
}

.tier-card ul {
  list-style: none;
}

.tier-card ul li {
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.tier-card.reserve ul li {
  border-color: rgba(255, 255, 255, 0.15);
}

.tier-card ul li::before {
  content: '★';
  color: var(--cream-dark);
  font-size: 0.75rem;
}

.tier-card.reserve ul li::before {
  color: var(--cream);
}

/* --- FAQ Accordion --- */
.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-lg) 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  color: var(--text-primary);
  cursor: pointer;
}

.faq-toggle svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-toggle.is-open svg {
  transform: rotate(180deg);
}

.faq-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-content p {
  padding-bottom: var(--space-lg);
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Animations --- */
@keyframes slideUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.animate-slide-up {
  animation: slideUp 0.6s ease-out forwards;
}

.animate-fade-in {
  animation: fadeIn 0.4s ease-out forwards;
}

/* Stagger delays */
.delay-100 { animation-delay: 100ms; }
.delay-200 { animation-delay: 200ms; }
.delay-300 { animation-delay: 300ms; }
.delay-400 { animation-delay: 400ms; }

/* --- Menu Item Card --- */
.menu-item {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-lg);
  border-radius: var(--radius-lg);
  transition: background-color var(--transition-fast);
  cursor: pointer;
}

.menu-item:hover {
  background-color: var(--warm-gray);
}

.menu-item-img {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-full);
  object-fit: cover;
  background-color: var(--cream-light);
  flex-shrink: 0;
}

.menu-item-info h4 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 2px;
}

.menu-item-info p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* --- Map Placeholder --- */
.map-container {
  width: 100%;
  height: 400px;
  background-color: var(--warm-gray);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.map-container::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent 49%, var(--border-color) 49%, var(--border-color) 51%, transparent 51%),
    linear-gradient(0deg, transparent 49%, var(--border-color) 49%, var(--border-color) 51%, transparent 51%);
  background-size: 60px 60px;
  opacity: 0.3;
}

.map-placeholder {
  text-align: center;
  z-index: 1;
}

.map-placeholder svg {
  width: 48px;
  height: 48px;
  stroke: var(--green-primary);
  margin-bottom: var(--space-md);
}

.map-placeholder p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Map pins */
.map-pins {
  position: absolute;
  inset: 0;
  z-index: 2;
}

.map-pin {
  position: absolute;
  width: 32px;
  height: 32px;
  background-color: var(--green-primary);
  border-radius: var(--radius-full);
  border: 3px solid white;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: scaleIn 0.4s ease-out;
}

.map-pin::after {
  content: '';
  width: 8px;
  height: 8px;
  background-color: white;
  border-radius: var(--radius-full);
}

/* --- Search Suggestions --- */
.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background-color: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  z-index: 50;
  display: none;
}

.search-suggestions.is-visible {
  display: block;
  animation: fadeIn 0.2s ease-out;
}

.search-suggestion-item {
  padding: var(--space-md);
  font-size: 0.9375rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  transition: background-color var(--transition-fast);
}

.search-suggestion-item:hover {
  background-color: var(--warm-gray);
}

.search-suggestion-item svg {
  width: 16px;
  height: 16px;
  stroke: var(--text-muted);
  flex-shrink: 0;
}

/* --- Responsive Helpers --- */
@media (max-width: 767px) {
  .hide-mobile {
    display: none !important;
  }
}

@media (min-width: 768px) {
  .hide-desktop {
    display: none !important;
  }
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background-color: var(--text-muted);
}
