/* ===== GreenBean Coffee Design System ===== */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Playfair+Display:wght@400;500;600;700&display=swap');

/* --- CSS Custom Properties --- */
:root {
  /* Brand Colors */
  --green-primary: #00824A;
  --green-dark: #005C35;
  --green-light: #E8F5EE;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF6E3;
  --cream-dark: #E8C97A;
  --brown: #5C3D2E;
  --brown-light: #8B6B4A;
  --brown-dark: #3E2518;
  --warm-white: #FFFDF7;
  --warm-gray: #F7F4EE;
  --text-primary: #1E1E1E;
  --text-secondary: #5A5A5A;
  --text-muted: #8A8A8A;
  --border-color: #E5E0D5;
  --shadow-color: rgba(50, 70, 47, 0.08);

  /* Semantic Colors */
  --bg-primary: var(--warm-white);
  --bg-secondary: var(--warm-gray);
  --bg-accent: var(--green-primary);
  --text-on-accent: #FFFFFF;
  --text-on-cream: var(--forest);

  /* Typography */
  --font-heading: 'Playfair Display', Georgia, serif;
  --font-body: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.625rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px var(--shadow-color);
  --shadow-md: 0 4px 12px var(--shadow-color);
  --shadow-lg: 0 8px 24px var(--shadow-color);
  --shadow-xl: 0 16px 48px var(--shadow-color);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-primary);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
}

/* --- Utility Classes --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

@media (min-width: 1024px) {
  .container {
    padding: 0 var(--space-2xl);
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.75rem;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 44px;
}

.btn-primary {
  background-color: var(--green-primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--green-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-secondary {
  background-color: transparent;
  color: var(--green-primary);
  border: 1.5px solid var(--green-primary);
}

.btn-secondary:hover {
  background-color: var(--green-light);
}

.btn-cream {
  background-color: var(--cream);
  color: var(--forest);
}

.btn-cream:hover {
  background-color: var(--cream-dark);
  transform: translateY(-1px);
}

.btn-dark {
  background-color: var(--forest);
  color: white;
}

.btn-dark:hover {
  background-color: var(--brown-dark);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  padding: 0.5rem 1rem;
}

.btn-ghost:hover {
  background-color: var(--warm-gray);
}

.btn-sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.0625rem;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--warm-white);
  border-bottom: 1px solid var(--border-color);
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.375rem;
  color: var(--green-primary);
  flex-shrink: 0;
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.header-nav {
  display: none;
  align-items: center;
  gap: var(--space-xl);
}

@media (min-width: 768px) {
  .header-nav {
    display: flex;
  }
}

.header-nav a {
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--text-primary);
  position: relative;
  padding: var(--space-xs) 0;
  transition: color var(--transition-fast);
}

.header-nav a:hover {
  color: var(--green-primary);
}

.header-nav a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--green-primary);
  transition: width var(--transition-base);
}

.header-nav a:hover::after,
.header-nav a.active::after {
  width: 100%;
}

.header-nav a.active {
  color: var(--green-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.header-actions .btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
}

.mobile-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
}

@media (min-width: 768px) {
  .mobile-menu-btn {
    display: none;
  }
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
  stroke: var(--text-primary);
}

/* Mobile Menu */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--warm-white);
  z-index: 99;
  padding: var(--space-xl);
  overflow-y: auto;
}

.mobile-nav.is-open {
  display: block;
  animation: slideDown 0.3s ease-out;
}

.mobile-nav a {
  display: block;
  padding: var(--space-md) 0;
  font-size: 1.25rem;
  font-weight: 500;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-primary);
}

.mobile-nav a:hover {
  color: var(--green-primary);
}

.mobile-nav .mobile-auth {
  margin-top: var(--space-xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background-color: var(--forest);
  color: white;
  padding: var(--space-lg);
  transform: translateY(100%);
  transition: transform 0.4s ease-out;
}

.cookie-banner.is-visible {
  transform: translateY(0);
}

.cookie-banner-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

@media (min-width: 768px) {
  .cookie-banner-inner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.cookie-banner p {
  font-size: 0.9375rem;
  line-height: 1.5;
  opacity: 0.9;
}

.cookie-banner-actions {
  display: flex;
  gap: var(--space-sm);
  flex-shrink: 0;
}

/* --- Footer --- */
.site-footer {
  background-color: var(--forest);
  color: white;
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-xl);
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

.footer-column h3 {
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
  color: white;
}

.footer-column ul li {
  margin-bottom: var(--space-sm);
}

.footer-column ul li a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.7);
  transition: color var(--transition-fast);
}

.footer-column ul li a:hover {
  color: white;
}

/* Footer accordion on mobile */
.footer-accordion-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-md) 0;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  color: white;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  cursor: pointer;
}

@media (min-width: 768px) {
  .footer-accordion-toggle {
    border-bottom: none;
    padding: 0 0 var(--space-md) 0;
    cursor: default;
  }
}

.footer-accordion-toggle svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-base);
}

@media (min-width: 768px) {
  .footer-accordion-toggle svg {
    display: none;
  }
}

.footer-accordion-toggle.is-open svg {
  transform: rotate(180deg);
}

.footer-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

@media (min-width: 768px) {
  .footer-accordion-content {
    max-height: none !important;
    overflow: visible;
  }
}

.footer-accordion-content ul {
  padding: var(--space-sm) 0 var(--space-md) 0;
}

.footer-bottom {
  margin-top: var(--space-3xl);
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  align-items: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: rgba(255, 255, 255, 0.5);
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-full);
  background-color: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.7);
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background-color: rgba(255, 255, 255, 0.2);
  color: white;
}

/* --- Section Styles --- */
.section {
  padding: var(--space-3xl) 0;
}

.section-lg {
  padding: var(--space-4xl) 0;
}

.section-cream {
  background-color: var(--cream-light);
}

.section-green {
  background-color: var(--green-primary);
  color: white;
}

.section-green-light {
  background-color: var(--green-light);
}

.section-dark {
  background-color: var(--forest);
  color: white;
}

.section-warm {
  background-color: var(--warm-gray);
}

/* --- Card Styles --- */
.card {
  background-color: white;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background-color: var(--warm-gray);
}

.card-body {
  padding: var(--space-lg);
}

.card-body h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-sm);
}

.card-body p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

/* --- Breadcrumb --- */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-md) 0;
  font-size: 0.875rem;
  color: var(--text-muted);
}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb .separator {
  color: var(--text-muted);
}

/* --- Tabs --- */
.tab-list {
  display: flex;
  gap: var(--space-xs);
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: var(--space-xs);
}

.tab-list::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  white-space: nowrap;
  color: var(--text-secondary);
  background-color: var(--warm-gray);
  transition: all var(--transition-fast);
  border: 1.5px solid transparent;
}

.tab-btn:hover {
  color: var(--green-primary);
  background-color: var(--green-light);
}

.tab-btn.is-active {
  color: white;
  background-color: var(--green-primary);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease-out;
}

.tab-panel.is-active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform 0.4s ease-out;
}

.carousel-slide {
  flex: 0 0 calc(33.333% - var(--space-lg) * 2 / 3);
  min-width: 0;
}

@media (max-width: 767px) {
  .carousel-slide {
    flex: 0 0 calc(80%);
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .carousel-slide {
    flex: 0 0 calc(50% - var(--space-lg) / 2);
  }
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background-color: white;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-50%) scale(1.05);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-btn:disabled:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-50%);
}

.carousel-btn-prev {
  left: var(--space-md);
}

.carousel-btn-next {
  right: var(--space-md);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
  stroke: var(--text-primary);
}

/* --- Gift Card Styles --- */
.gift-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
  aspect-ratio: 3/2;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: var(--space-lg);
  position: relative;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.gift-card-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.1;
}

.gift-card-content {
  position: relative;
  z-index: 1;
}

.gift-card-content h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.gift-card-content p {
  font-size: 0.75rem;
  opacity: 0.8;
}

/* --- Form Controls --- */
.input-group {
  position: relative;
}

.input-field {
  width: 100%;
  padding: 0.875rem 1rem;
  font-family: var(--font-body);
  font-size: 1rem;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: white;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.input-field:focus {
  outline: none;
  border-color: var(--green-primary);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.15);
}

.input-field::placeholder {
  color: var(--text-muted);
}

/* --- Toggle Switch --- */
.toggle-group {
  display: inline-flex;
  background-color: var(--warm-gray);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-btn {
  padding: 0.5rem 1.25rem;
  font-weight: 600;
  font-size: 0.875rem;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}

.toggle-btn.is-active {
  background-color: white;
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

/* --- Filter Panel --- */
.filter-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.filter-panel.is-open {
  max-height: 500px;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--green-primary);
}

/* --- Store Card --- */
.store-card {
  background-color: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 1px solid var(--border-color);
  transition: all var(--transition-base);
}

.store-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.store-card h3 {
  font-family: var(--font-body);
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.store-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.store-features {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin-top: var(--space-md);
}

.store-feature-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  background-color: var(--green-light);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
}

/* --- Sidebar --- */
.sidebar {
  width: 100%;
  border-right: 1px solid var(--border-color);
  padding: var(--space-xl);
}

@media (min-width: 1024px) {
  .sidebar {
    width: 280px;
    flex-shrink: 0;
    position: sticky;
    top: var(--header-height);
    height: calc(100vh - var(--header-height));
    overflow-y: auto;
  }
}

.sidebar-group {
  margin-bottom: var(--space-xl);
}

.sidebar-group h3 {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--green-primary);
  margin-bottom: var(--space-sm);
}

.sidebar-group ul li a {
  display: block;
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.sidebar-group ul li a:hover,
.sidebar-group ul li a.is-active {
  color: var(--green-primary);
  font-weight: 600;
}

/* --- Redemption Levels --- */
.redemption-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

@media (min-width: 768px) {
  .redemption-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .redemption-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.redemption-card {
  background-color: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 2px solid var(--border-color);
  text-align: center;
  transition: all var(--transition-base);
}

.redemption-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-md);
}

.redemption-card .stars {
  font-size: 2rem;
  color: var(--cream-dark);
  font-weight: 700;
  font-family: var(--font-heading);
  margin-bottom: var(--space-sm);
}

.redemption-card h4 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.redemption-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* --- Tier Cards --- */
.tier-card {
  background-color: white;
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  border: 2px solid var(--border-color);
  transition: all var(--transition-base);
}

.tier-card:hover {
  border-color: var(--green-primary);
}

.tier-card.gold {
  border-color: var(--cream);
  background: linear-gradient(135deg, #FFFDF7 0%, #FDF6E3 100%);
}

.tier-card.reserve {
  border-color: var(--forest);
  background: linear-gradient(135deg, var(--forest) 0%, #3E4A3C 100%);
  color: white;
}

.tier-card.reserve p,
.tier-card.reserve li {
  color: rgba(255, 255, 255, 0.8);
}

.tier-card h3 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xs);
}

.tier-card .tier-threshold {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}

.tier-card.reserve .tier-threshold {
  color: rgba(255, 255, 255, 0.5);
}

.tier-card ul {
  list-style: none;
}

.tier-card ul li {
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.tier-card.reserve ul li {
  border-color: rgba(255, 255, 255, 0.15);
}

.tier-card ul li::before {
  content: '★';
  color: var(--cream-dark);
  font-size: 0.75rem;
}

.tier-card.reserve ul li::before {
  color: var(--cream);
}

/* --- FAQ Accordion --- */
.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-lg) 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  color: var(--text-primary);
  cursor: pointer;
}

.faq-toggle svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-toggle.is-open svg {
  transform: rotate(180deg);
}

.faq-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-content p {
  padding-bottom: var(--space-lg);
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Animations --- */
@keyframes slideUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.animate-slide-up {
  animation: slideUp 0.6s ease-out forwards;
}

.animate-fade-in {
  animation: fadeIn 0.4s ease-out forwards;
}

/* Stagger delays */
.delay-100 { animation-delay: 100ms; }
.delay-200 { animation-delay: 200ms; }
.delay-300 { animation-delay: 300ms; }
.delay-400 { animation-delay: 400ms; }

/* --- Menu Item Card --- */
.menu-item {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-lg);
  border-radius: var(--radius-lg);
  transition: background-color var(--transition-fast);
  cursor: pointer;
}

.menu-item:hover {
  background-color: var(--warm-gray);
}

.menu-item-img {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-full);
  object-fit: cover;
  background-color: var(--cream-light);
  flex-shrink: 0;
}

.menu-item-info h4 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 2px;
}

.menu-item-info p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* --- Map Placeholder --- */
.map-container {
  width: 100%;
  height: 400px;
  background-color: var(--warm-gray);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.map-container::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent 49%, var(--border-color) 49%, var(--border-color) 51%, transparent 51%),
    linear-gradient(0deg, transparent 49%, var(--border-color) 49%, var(--border-color) 51%, transparent 51%);
  background-size: 60px 60px;
  opacity: 0.3;
}

.map-placeholder {
  text-align: center;
  z-index: 1;
}

.map-placeholder svg {
  width: 48px;
  height: 48px;
  stroke: var(--green-primary);
  margin-bottom: var(--space-md);
}

.map-placeholder p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Map pins */
.map-pins {
  position: absolute;
  inset: 0;
  z-index: 2;
}

.map-pin {
  position: absolute;
  width: 32px;
  height: 32px;
  background-color: var(--green-primary);
  border-radius: var(--radius-full);
  border: 3px solid white;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: scaleIn 0.4s ease-out;
}

.map-pin::after {
  content: '';
  width: 8px;
  height: 8px;
  background-color: white;
  border-radius: var(--radius-full);
}

/* --- Search Suggestions --- */
.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background-color: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  z-index: 50;
  display: none;
}

.search-suggestions.is-visible {
  display: block;
  animation: fadeIn 0.2s ease-out;
}

.search-suggestion-item {
  padding: var(--space-md);
  font-size: 0.9375rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  transition: background-color var(--transition-fast);
}

.search-suggestion-item:hover {
  background-color: var(--warm-gray);
}

.search-suggestion-item svg {
  width: 16px;
  height: 16px;
  stroke: var(--text-muted);
  flex-shrink: 0;
}

/* --- Responsive Helpers --- */
@media (max-width: 767px) {
  .hide-mobile {
    display: none !important;
  }
}

@media (min-width: 768px) {
  .hide-desktop {
    display: none !important;
  }
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background-color: var(--text-muted);
}

/* ===== GreenBean Coffee Design System ===== */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Playfair+Display:wght@400;500;600;700&display=swap');

/* --- CSS Custom Properties --- */
:root {
  /* Brand Colors */
  --green-primary: #00824A;
  --green-dark: #005C35;
  --green-light: #E8F5EE;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF6E3;
  --cream-dark: #E8C97A;
  --brown: #5C3D2E;
  --brown-light: #8B6B4A;
  --brown-dark: #3E2518;
  --warm-white: #FFFDF7;
  --warm-gray: #F7F4EE;
  --text-primary: #1E1E1E;
  --text-secondary: #5A5A5A;
  --text-muted: #8A8A8A;
  --border-color: #E5E0D5;
  --shadow-color: rgba(50, 70, 47, 0.08);

  /* Semantic Colors */
  --bg-primary: var(--warm-white);
  --bg-secondary: var(--warm-gray);
  --bg-accent: var(--green-primary);
  --text-on-accent: #FFFFFF;
  --text-on-cream: var(--forest);

  /* Typography */
  --font-heading: 'Playfair Display', Georgia, serif;
  --font-body: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.625rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px var(--shadow-color);
  --shadow-md: 0 4px 12px var(--shadow-color);
  --shadow-lg: 0 8px 24px var(--shadow-color);
  --shadow-xl: 0 16px 48px var(--shadow-color);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-primary);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
}

/* --- Utility Classes --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

@media (min-width: 1024px) {
  .container {
    padding: 0 var(--space-2xl);
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.75rem;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 44px;
}

.btn-primary {
  background-color: var(--green-primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--green-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-secondary {
  background-color: transparent;
  color: var(--green-primary);
  border: 1.5px solid var(--green-primary);
}

.btn-secondary:hover {
  background-color: var(--green-light);
}

.btn-cream {
  background-color: var(--cream);
  color: var(--forest);
}

.btn-cream:hover {
  background-color: var(--cream-dark);
  transform: translateY(-1px);
}

.btn-dark {
  background-color: var(--forest);
  color: white;
}

.btn-dark:hover {
  background-color: var(--brown-dark);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  padding: 0.5rem 1rem;
}

.btn-ghost:hover {
  background-color: var(--warm-gray);
}

.btn-sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.0625rem;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--warm-white);
  border-bottom: 1px solid var(--border-color);
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.375rem;
  color: var(--green-primary);
  flex-shrink: 0;
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.header-nav {
  display: none;
  align-items: center;
  gap: var(--space-xl);
}

@media (min-width: 768px) {
  .header-nav {
    display: flex;
  }
}

.header-nav a {
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--text-primary);
  position: relative;
  padding: var(--space-xs) 0;
  transition: color var(--transition-fast);
}

.header-nav a:hover {
  color: var(--green-primary);
}

.header-nav a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--green-primary);
  transition: width var(--transition-base);
}

.header-nav a:hover::after,
.header-nav a.active::after {
  width: 100%;
}

.header-nav a.active {
  color: var(--green-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.header-actions .btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
}

.mobile-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
}

@media (min-width: 768px) {
  .mobile-menu-btn {
    display: none;
  }
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
  stroke: var(--text-primary);
}

/* Mobile Menu */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--warm-white);
  z-index: 99;
  padding: var(--space-xl);
  overflow-y: auto;
}

.mobile-nav.is-open {
  display: block;
  animation: slideDown 0.3s ease-out;
}

.mobile-nav a {
  display: block;
  padding: var(--space-md) 0;
  font-size: 1.25rem;
  font-weight: 500;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-primary);
}

.mobile-nav a:hover {
  color: var(--green-primary);
}

.mobile-nav .mobile-auth {
  margin-top: var(--space-xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background-color: var(--forest);
  color: white;
  padding: var(--space-lg);
  transform: translateY(100%);
  transition: transform 0.4s ease-out;
}

.cookie-banner.is-visible {
  transform: translateY(0);
}

.cookie-banner-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

@media (min-width: 768px) {
  .cookie-banner-inner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.cookie-banner p {
  font-size: 0.9375rem;
  line-height: 1.5;
  opacity: 0.9;
}

.cookie-banner-actions {
  display: flex;
  gap: var(--space-sm);
  flex-shrink: 0;
}

/* --- Footer --- */
.site-footer {
  background-color: var(--forest);
  color: white;
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-xl);
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

.footer-column h3 {
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
  color: white;
}

.footer-column ul li {
  margin-bottom: var(--space-sm);
}

.footer-column ul li a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.7);
  transition: color var(--transition-fast);
}

.footer-column ul li a:hover {
  color: white;
}

/* Footer accordion on mobile */
.footer-accordion-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-md) 0;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  color: white;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  cursor: pointer;
}

@media (min-width: 768px) {
  .footer-accordion-toggle {
    border-bottom: none;
    padding: 0 0 var(--space-md) 0;
    cursor: default;
  }
}

.footer-accordion-toggle svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-base);
}

@media (min-width: 768px) {
  .footer-accordion-toggle svg {
    display: none;
  }
}

.footer-accordion-toggle.is-open svg {
  transform: rotate(180deg);
}

.footer-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

@media (min-width: 768px) {
  .footer-accordion-content {
    max-height: none !important;
    overflow: visible;
  }
}

.footer-accordion-content ul {
  padding: var(--space-sm) 0 var(--space-md) 0;
}

.footer-bottom {
  margin-top: var(--space-3xl);
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  align-items: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: rgba(255, 255, 255, 0.5);
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-full);
  background-color: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.7);
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background-color: rgba(255, 255, 255, 0.2);
  color: white;
}

/* --- Section Styles --- */
.section {
  padding: var(--space-3xl) 0;
}

.section-lg {
  padding: var(--space-4xl) 0;
}

.section-cream {
  background-color: var(--cream-light);
}

.section-green {
  background-color: var(--green-primary);
  color: white;
}

.section-green-light {
  background-color: var(--green-light);
}

.section-dark {
  background-color: var(--forest);
  color: white;
}

.section-warm {
  background-color: var(--warm-gray);
}

/* --- Card Styles --- */
.card {
  background-color: white;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background-color: var(--warm-gray);
}

.card-body {
  padding: var(--space-lg);
}

.card-body h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-sm);
}

.card-body p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

/* --- Breadcrumb --- */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-md) 0;
  font-size: 0.875rem;
  color: var(--text-muted);
}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb .separator {
  color: var(--text-muted);
}

/* --- Tabs --- */
.tab-list {
  display: flex;
  gap: var(--space-xs);
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: var(--space-xs);
}

.tab-list::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  white-space: nowrap;
  color: var(--text-secondary);
  background-color: var(--warm-gray);
  transition: all var(--transition-fast);
  border: 1.5px solid transparent;
}

.tab-btn:hover {
  color: var(--green-primary);
  background-color: var(--green-light);
}

.tab-btn.is-active {
  color: white;
  background-color: var(--green-primary);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease-out;
}

.tab-panel.is-active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform 0.4s ease-out;
}

.carousel-slide {
  flex: 0 0 calc(33.333% - var(--space-lg) * 2 / 3);
  min-width: 0;
}

@media (max-width: 767px) {
  .carousel-slide {
    flex: 0 0 calc(80%);
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .carousel-slide {
    flex: 0 0 calc(50% - var(--space-lg) / 2);
  }
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background-color: white;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-50%) scale(1.05);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-btn:disabled:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-50%);
}

.carousel-btn-prev {
  left: var(--space-md);
}

.carousel-btn-next {
  right: var(--space-md);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
  stroke: var(--text-primary);
}

/* --- Gift Card Styles --- */
.gift-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
  aspect-ratio: 3/2;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: var(--space-lg);
  position: relative;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.gift-card-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.1;
}

.gift-card-content {
  position: relative;
  z-index: 1;
}

.gift-card-content h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.gift-card-content p {
  font-size: 0.75rem;
  opacity: 0.8;
}

/* --- Form Controls --- */
.input-group {
  position: relative;
}

.input-field {
  width: 100%;
  padding: 0.875rem 1rem;
  font-family: var(--font-body);
  font-size: 1rem;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: white;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.input-field:focus {
  outline: none;
  border-color: var(--green-primary);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.15);
}

.input-field::placeholder {
  color: var(--text-muted);
}

/* --- Toggle Switch --- */
.toggle-group {
  display: inline-flex;
  background-color: var(--warm-gray);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-btn {
  padding: 0.5rem 1.25rem;
  font-weight: 600;
  font-size: 0.875rem;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}

.toggle-btn.is-active {
  background-color: white;
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

/* --- Filter Panel --- */
.filter-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.filter-panel.is-open {
  max-height: 500px;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--green-primary);
}

/* --- Store Card --- */
.store-card {
  background-color: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 1px solid var(--border-color);
  transition: all var(--transition-base);
}

.store-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.store-card h3 {
  font-family: var(--font-body);
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.store-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.store-features {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin-top: var(--space-md);
}

.store-feature-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  background-color: var(--green-light);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
}

/* --- Sidebar --- */
.sidebar {
  width: 100%;
  border-right: 1px solid var(--border-color);
  padding: var(--space-xl);
}

@media (min-width: 1024px) {
  .sidebar {
    width: 280px;
    flex-shrink: 0;
    position: sticky;
    top: var(--header-height);
    height: calc(100vh - var(--header-height));
    overflow-y: auto;
  }
}

.sidebar-group {
  margin-bottom: var(--space-xl);
}

.sidebar-group h3 {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--green-primary);
  margin-bottom: var(--space-sm);
}

.sidebar-group ul li a {
  display: block;
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.sidebar-group ul li a:hover,
.sidebar-group ul li a.is-active {
  color: var(--green-primary);
  font-weight: 600;
}

/* --- Redemption Levels --- */
.redemption-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

@media (min-width: 768px) {
  .redemption-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .redemption-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.redemption-card {
  background-color: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 2px solid var(--border-color);
  text-align: center;
  transition: all var(--transition-base);
}

.redemption-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-md);
}

.redemption-card .stars {
  font-size: 2rem;
  color: var(--cream-dark);
  font-weight: 700;
  font-family: var(--font-heading);
  margin-bottom: var(--space-sm);
}

.redemption-card h4 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.redemption-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* --- Tier Cards --- */
.tier-card {
  background-color: white;
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  border: 2px solid var(--border-color);
  transition: all var(--transition-base);
}

.tier-card:hover {
  border-color: var(--green-primary);
}

.tier-card.gold {
  border-color: var(--cream);
  background: linear-gradient(135deg, #FFFDF7 0%, #FDF6E3 100%);
}

.tier-card.reserve {
  border-color: var(--forest);
  background: linear-gradient(135deg, var(--forest) 0%, #3E4A3C 100%);
  color: white;
}

.tier-card.reserve p,
.tier-card.reserve li {
  color: rgba(255, 255, 255, 0.8);
}

.tier-card h3 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xs);
}

.tier-card .tier-threshold {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}

.tier-card.reserve .tier-threshold {
  color: rgba(255, 255, 255, 0.5);
}

.tier-card ul {
  list-style: none;
}

.tier-card ul li {
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.tier-card.reserve ul li {
  border-color: rgba(255, 255, 255, 0.15);
}

.tier-card ul li::before {
  content: '★';
  color: var(--cream-dark);
  font-size: 0.75rem;
}

.tier-card.reserve ul li::before {
  color: var(--cream);
}

/* --- FAQ Accordion --- */
.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-lg) 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  color: var(--text-primary);
  cursor: pointer;
}

.faq-toggle svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-toggle.is-open svg {
  transform: rotate(180deg);
}

.faq-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-content p {
  padding-bottom: var(--space-lg);
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Animations --- */
@keyframes slideUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.animate-slide-up {
  animation: slideUp 0.6s ease-out forwards;
}

.animate-fade-in {
  animation: fadeIn 0.4s ease-out forwards;
}

/* Stagger delays */
.delay-100 { animation-delay: 100ms; }
.delay-200 { animation-delay: 200ms; }
.delay-300 { animation-delay: 300ms; }
.delay-400 { animation-delay: 400ms; }

/* --- Menu Item Card --- */
.menu-item {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-lg);
  border-radius: var(--radius-lg);
  transition: background-color var(--transition-fast);
  cursor: pointer;
}

.menu-item:hover {
  background-color: var(--warm-gray);
}

.menu-item-img {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-full);
  object-fit: cover;
  background-color: var(--cream-light);
  flex-shrink: 0;
}

.menu-item-info h4 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 2px;
}

.menu-item-info p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* --- Map Placeholder --- */
.map-container {
  width: 100%;
  height: 400px;
  background-color: var(--warm-gray);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.map-container::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent 49%, var(--border-color) 49%, var(--border-color) 51%, transparent 51%),
    linear-gradient(0deg, transparent 49%, var(--border-color) 49%, var(--border-color) 51%, transparent 51%);
  background-size: 60px 60px;
  opacity: 0.3;
}

.map-placeholder {
  text-align: center;
  z-index: 1;
}

.map-placeholder svg {
  width: 48px;
  height: 48px;
  stroke: var(--green-primary);
  margin-bottom: var(--space-md);
}

.map-placeholder p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Map pins */
.map-pins {
  position: absolute;
  inset: 0;
  z-index: 2;
}

.map-pin {
  position: absolute;
  width: 32px;
  height: 32px;
  background-color: var(--green-primary);
  border-radius: var(--radius-full);
  border: 3px solid white;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: scaleIn 0.4s ease-out;
}

.map-pin::after {
  content: '';
  width: 8px;
  height: 8px;
  background-color: white;
  border-radius: var(--radius-full);
}

/* --- Search Suggestions --- */
.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background-color: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  z-index: 50;
  display: none;
}

.search-suggestions.is-visible {
  display: block;
  animation: fadeIn 0.2s ease-out;
}

.search-suggestion-item {
  padding: var(--space-md);
  font-size: 0.9375rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  transition: background-color var(--transition-fast);
}

.search-suggestion-item:hover {
  background-color: var(--warm-gray);
}

.search-suggestion-item svg {
  width: 16px;
  height: 16px;
  stroke: var(--text-muted);
  flex-shrink: 0;
}

/* --- Responsive Helpers --- */
@media (max-width: 767px) {
  .hide-mobile {
    display: none !important;
  }
}

@media (min-width: 768px) {
  .hide-desktop {
    display: none !important;
  }
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background-color: var(--text-muted);
}

raw_arguments.content:
/* ===== GreenBean Coffee Design System ===== */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Playfair+Display:wght@400;500;600;700&display=swap');

/* --- CSS Custom Properties --- */
:root {
  /* Brand Colors */
  --green-primary: #00824A;
  --green-dark: #005C35;
  --green-light: #E8F5EE;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF6E3;
  --cream-dark: #E8C97A;
  --brown: #5C3D2E;
  --brown-light: #8B6B4A;
  --brown-dark: #3E2518;
  --warm-white: #FFFDF7;
  --warm-gray: #F7F4EE;
  --text-primary: #1E1E1E;
  --text-secondary: #5A5A5A;
  --text-muted: #8A8A8A;
  --border-color: #E5E0D5;
  --shadow-color: rgba(50, 70, 47, 0.08);

  /* Semantic Colors */
  --bg-primary: var(--warm-white);
  --bg-secondary: var(--warm-gray);
  --bg-accent: var(--green-primary);
  --text-on-accent: #FFFFFF;
  --text-on-cream: var(--forest);

  /* Typography */
  --font-heading: 'Playfair Display', Georgia, serif;
  --font-body: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.625rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px var(--shadow-color);
  --shadow-md: 0 4px 12px var(--shadow-color);
  --shadow-lg: 0 8px 24px var(--shadow-color);
  --shadow-xl: 0 16px 48px var(--shadow-color);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-primary);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
}

/* --- Utility Classes --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

@media (min-width: 1024px) {
  .container {
    padding: 0 var(--space-2xl);
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.75rem;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 44px;
}

.btn-primary {
  background-color: var(--green-primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--green-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-secondary {
  background-color: transparent;
  color: var(--green-primary);
  border: 1.5px solid var(--green-primary);
}

.btn-secondary:hover {
  background-color: var(--green-light);
}

.btn-cream {
  background-color: var(--cream);
  color: var(--forest);
}

.btn-cream:hover {
  background-color: var(--cream-dark);
  transform: translateY(-1px);
}

.btn-dark {
  background-color: var(--forest);
  color: white;
}

.btn-dark:hover {
  background-color: var(--brown-dark);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  padding: 0.5rem 1rem;
}

.btn-ghost:hover {
  background-color: var(--warm-gray);
}

.btn-sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.0625rem;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--warm-white);
  border-bottom: 1px solid var(--border-color);
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.375rem;
  color: var(--green-primary);
  flex-shrink: 0;
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.header-nav {
  display: none;
  align-items: center;
  gap: var(--space-xl);
}

@media (min-width: 768px) {
  .header-nav {
    display: flex;
  }
}

.header-nav a {
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--text-primary);
  position: relative;
  padding: var(--space-xs) 0;
  transition: color var(--transition-fast);
}

.header-nav a:hover {
  color: var(--green-primary);
}

.header-nav a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--green-primary);
  transition: width var(--transition-base);
}

.header-nav a:hover::after,
.header-nav a.active::after {
  width: 100%;
}

.header-nav a.active {
  color: var(--green-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.header-actions .btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
}

.mobile-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
}

@media (min-width: 768px) {
  .mobile-menu-btn {
    display: none;
  }
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
  stroke: var(--text-primary);
}

/* Mobile Menu */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--warm-white);
  z-index: 99;
  padding: var(--space-xl);
  overflow-y: auto;
}

.mobile-nav.is-open {
  display: block;
  animation: slideDown 0.3s ease-out;
}

.mobile-nav a {
  display: block;
  padding: var(--space-md) 0;
  font-size: 1.25rem;
  font-weight: 500;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-primary);
}

.mobile-nav a:hover {
  color: var(--green-primary);
}

.mobile-nav .mobile-auth {
  margin-top: var(--space-xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background-color: var(--forest);
  color: white;
  padding: var(--space-lg);
  transform: translateY(100%);
  transition: transform 0.4s ease-out;
}

.cookie-banner.is-visible {
  transform: translateY(0);
}

.cookie-banner-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

@media (min-width: 768px) {
  .cookie-banner-inner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.cookie-banner p {
  font-size: 0.9375rem;
  line-height: 1.5;
  opacity: 0.9;
}

.cookie-banner-actions {
  display: flex;
  gap: var(--space-sm);
  flex-shrink: 0;
}

/* --- Footer --- */
.site-footer {
  background-color: var(--forest);
  color: white;
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-xl);
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

.footer-column h3 {
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
  color: white;
}

.footer-column ul li {
  margin-bottom: var(--space-sm);
}

.footer-column ul li a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.7);
  transition: color var(--transition-fast);
}

.footer-column ul li a:hover {
  color: white;
}

/* Footer accordion on mobile */
.footer-accordion-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-md) 0;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  color: white;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  cursor: pointer;
}

@media (min-width: 768px) {
  .footer-accordion-toggle {
    border-bottom: none;
    padding: 0 0 var(--space-md) 0;
    cursor: default;
  }
}

.footer-accordion-toggle svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-base);
}

@media (min-width: 768px) {
  .footer-accordion-toggle svg {
    display: none;
  }
}

.footer-accordion-toggle.is-open svg {
  transform: rotate(180deg);
}

.footer-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

@media (min-width: 768px) {
  .footer-accordion-content {
    max-height: none !important;
    overflow: visible;
  }
}

.footer-accordion-content ul {
  padding: var(--space-sm) 0 var(--space-md) 0;
}

.footer-bottom {
  margin-top: var(--space-3xl);
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  align-items: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: rgba(255, 255, 255, 0.5);
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-full);
  background-color: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.7);
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background-color: rgba(255, 255, 255, 0.2);
  color: white;
}

/* --- Section Styles --- */
.section {
  padding: var(--space-3xl) 0;
}

.section-lg {
  padding: var(--space-4xl) 0;
}

.section-cream {
  background-color: var(--cream-light);
}

.section-green {
  background-color: var(--green-primary);
  color: white;
}

.section-green-light {
  background-color: var(--green-light);
}

.section-dark {
  background-color: var(--forest);
  color: white;
}

.section-warm {
  background-color: var(--warm-gray);
}

/* --- Card Styles --- */
.card {
  background-color: white;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background-color: var(--warm-gray);
}

.card-body {
  padding: var(--space-lg);
}

.card-body h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-sm);
}

.card-body p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

/* --- Breadcrumb --- */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-md) 0;
  font-size: 0.875rem;
  color: var(--text-muted);
}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb .separator {
  color: var(--text-muted);
}

/* --- Tabs --- */
.tab-list {
  display: flex;
  gap: var(--space-xs);
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: var(--space-xs);
}

.tab-list::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  white-space: nowrap;
  color: var(--text-secondary);
  background-color: var(--warm-gray);
  transition: all var(--transition-fast);
  border: 1.5px solid transparent;
}

.tab-btn:hover {
  color: var(--green-primary);
  background-color: var(--green-light);
}

.tab-btn.is-active {
  color: white;
  background-color: var(--green-primary);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease-out;
}

.tab-panel.is-active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform 0.4s ease-out;
}

.carousel-slide {
  flex: 0 0 calc(33.333% - var(--space-lg) * 2 / 3);
  min-width: 0;
}

@media (max-width: 767px) {
  .carousel-slide {
    flex: 0 0 calc(80%);
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .carousel-slide {
    flex: 0 0 calc(50% - var(--space-lg) / 2);
  }
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background-color: white;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-50%) scale(1.05);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-btn:disabled:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-50%);
}

.carousel-btn-prev {
  left: var(--space-md);
}

.carousel-btn-next {
  right: var(--space-md);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
  stroke: var(--text-primary);
}

/* --- Gift Card Styles --- */
.gift-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
  aspect-ratio: 3/2;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: var(--space-lg);
  position: relative;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.gift-card-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.1;
}

.gift-card-content {
  position: relative;
  z-index: 1;
}

.gift-card-content h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.gift-card-content p {
  font-size: 0.75rem;
  opacity: 0.8;
}

/* --- Form Controls --- */
.input-group {
  position: relative;
}

.input-field {
  width: 100%;
  padding: 0.875rem 1rem;
  font-family: var(--font-body);
  font-size: 1rem;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: white;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.input-field:focus {
  outline: none;
  border-color: var(--green-primary);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.15);
}

.input-field::placeholder {
  color: var(--text-muted);
}

/* --- Toggle Switch --- */
.toggle-group {
  display: inline-flex;
  background-color: var(--warm-gray);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-btn {
  padding: 0.5rem 1.25rem;
  font-weight: 600;
  font-size: 0.875rem;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}

.toggle-btn.is-active {
  background-color: white;
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

/* --- Filter Panel --- */
.filter-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.filter-panel.is-open {
  max-height: 500px;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--green-primary);
}

/* --- Store Card --- */
.store-card {
  background-color: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 1px solid var(--border-color);
  transition: all var(--transition-base);
}

.store-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.store-card h3 {
  font-family: var(--font-body);
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.store-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.store-features {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin-top: var(--space-md);
}

.store-feature-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  background-color: var(--green-light);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
}

/* --- Sidebar --- */
.sidebar {
  width: 100%;
  border-right: 1px solid var(--border-color);
  padding: var(--space-xl);
}

@media (min-width: 1024px) {
  .sidebar {
    width: 280px;
    flex-shrink: 0;
    position: sticky;
    top: var(--header-height);
    height: calc(100vh - var(--header-height));
    overflow-y: auto;
  }
}

.sidebar-group {
  margin-bottom: var(--space-xl);
}

.sidebar-group h3 {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--green-primary);
  margin-bottom: var(--space-sm);
}

.sidebar-group ul li a {
  display: block;
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.sidebar-group ul li a:hover,
.sidebar-group ul li a.is-active {
  color: var(--green-primary);
  font-weight: 600;
}

/* --- Redemption Levels --- */
.redemption-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

@media (min-width: 768px) {
  .redemption-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .redemption-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.redemption-card {
  background-color: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 2px solid var(--border-color);
  text-align: center;
  transition: all var(--transition-base);
}

.redemption-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-md);
}

.redemption-card .stars {
  font-size: 2rem;
  color: var(--cream-dark);
  font-weight: 700;
  font-family: var(--font-heading);
  margin-bottom: var(--space-sm);
}

.redemption-card h4 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.redemption-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* --- Tier Cards --- */
.tier-card {
  background-color: white;
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  border: 2px solid var(--border-color);
  transition: all var(--transition-base);
}

.tier-card:hover {
  border-color: var(--green-primary);
}

.tier-card.gold {
  border-color: var(--cream);
  background: linear-gradient(135deg, #FFFDF7 0%, #FDF6E3 100%);
}

.tier-card.reserve {
  border-color: var(--forest);
  background: linear-gradient(135deg, var(--forest) 0%, #3E4A3C 100%);
  color: white;
}

.tier-card.reserve p,
.tier-card.reserve li {
  color: rgba(255, 255, 255, 0.8);
}

.tier-card h3 {
  font-size: 1.5rem;
  margin-bottom: var(--space-xs);
}

.tier-card .tier-threshold {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}

.tier-card.reserve .tier-threshold {
  color: rgba(255, 255, 255, 0.5);
}

.tier-card ul {
  list-style: none;
}

.tier-card ul li {
  padding: var(--space-sm) 0;
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.tier-card.reserve ul li {
  border-color: rgba(255, 255, 255, 0.15);
}

.tier-card ul li::before {
  content: '★';
  color: var(--cream-dark);
  font-size: 0.75rem;
}

.tier-card.reserve ul li::before {
  color: var(--cream);
}

/* --- FAQ Accordion --- */
.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-lg) 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  color: var(--text-primary);
  cursor: pointer;
}

.faq-toggle svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-toggle.is-open svg {
  transform: rotate(180deg);
}

.faq-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-content p {
  padding-bottom: var(--space-lg);
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Animations --- */
@keyframes slideUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.animate-slide-up {
  animation: slideUp 0.6s ease-out forwards;
}

.animate-fade-in {
  animation: fadeIn 0.4s ease-out forwards;
}

/* Stagger delays */
.delay-100 { animation-delay: 100ms; }
.delay-200 { animation-delay: 200ms; }
.delay-300 { animation-delay: 300ms; }
.delay-400 { animation-delay: 400ms; }

/* --- Menu Item Card --- */
.menu-item {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-lg);
  border-radius: var(--radius-lg);
  transition: background-color var(--transition-fast);
  cursor: pointer;
}

.menu-item:hover {
  background-color: var(--warm-gray);
}

.menu-item-img {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-full);
  object-fit: cover;
  background-color: var(--cream-light);
  flex-shrink: 0;
}

.menu-item-info h4 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 2px;
}

.menu-item-info p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* --- Map Placeholder --- */
.map-container {
  width: 100%;
  height: 400px;
  background-color: var(--warm-gray);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.map-container::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent 49%, var(--border-color) 49%, var(--border-color) 51%, transparent 51%),
    linear-gradient(0deg, transparent 49%, var(--border-color) 49%, var(--border-color) 51%, transparent 51%);
  background-size: 60px 60px;
  opacity: 0.3;
}

.map-placeholder {
  text-align: center;
  z-index: 1;
}

.map-placeholder svg {
  width: 48px;
  height: 48px;
  stroke: var(--green-primary);
  margin-bottom: var(--space-md);
}

.map-placeholder p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Map pins */
.map-pins {
  position: absolute;
  inset: 0;
  z-index: 2;
}

.map-pin {
  position: absolute;
  width: 32px;
  height: 32px;
  background-color: var(--green-primary);
  border-radius: var(--radius-full);
  border: 3px solid white;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: scaleIn 0.4s ease-out;
}

.map-pin::after {
  content: '';
  width: 8px;
  height: 8px;
  background-color: white;
  border-radius: var(--radius-full);
}

/* --- Search Suggestions --- */
.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background-color: white;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  z-index: 50;
  display: none;
}

.search-suggestions.is-visible {
  display: block;
  animation: fadeIn 0.2s ease-out;
}

.search-suggestion-item {
  padding: var(--space-md);
  font-size: 0.9375rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  transition: background-color var(--transition-fast);
}

.search-suggestion-item:hover {
  background-color: var(--warm-gray);
}

.search-suggestion-item svg {
  width: 16px;
  height: 16px;
  stroke: var(--text-muted);
  flex-shrink: 0;
}

/* --- Responsive Helpers --- */
@media (max-width: 767px) {
  .hide-mobile {
    display: none !important;
  }
}

@media (min-width: 768px) {
  .hide-desktop {
    display: none !important;
  }
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background-color: var(--text-muted);
}

